void process_lru_command(conn *c, token_t *tokens, size_t ntokens) {
    if (ntokens < 2) {
        conn_send(c, "ERROR: Invalid command format.\r\n", strlen("ERROR: Invalid command format.\r\n"));
        return;
    }

    if (strncmp(tokens[0].value, "tune", tokens[0].length) == 0) {
        if (ntokens != 4) {
            conn_send(c, "ERROR: 'tune' command requires hot%, warm%, and age factor.\r\n", strlen("ERROR: 'tune' command requires hot%, warm%, and age factor.\r\n"));
            return;
        }

        double hot_pct = atof(tokens[1].value);
        double warm_pct = atof(tokens[2].value);
        double age_factor = atof(tokens[3].value);

        if (hot_pct < 0 || hot_pct > 100 || warm_pct < 0 || warm_pct > 100 || age_factor <= 0) {
            conn_send(c, "ERROR: Invalid values for 'tune' command.\r\n", strlen("ERROR: Invalid values for 'tune' command.\r\n"));
            return;
        }

        lru_tune_settings(hot_pct, warm_pct, age_factor);
        conn_send(c, "OK: LRU settings updated.\r\n", strlen("OK: LRU settings updated.\r\n"));
    }
    else if (strncmp(tokens[0].value, "mode", tokens[0].length) == 0) {
        if (ntokens != 2) {
            conn_send(c, "ERROR: 'mode' command requires an argument (flat/segmented).\r\n", strlen("ERROR: 'mode' command requires an argument (flat/segmented).\r\n"));
            return;
        }

        if (strncmp(tokens[1].value, "flat", tokens[1].length) == 0) {
            lru_set_mode(LRU_MODE_FLAT);
            conn_send(c, "OK: LRU mode set to flat.\r\n", strlen("OK: LRU mode set to flat.\r\n"));
        }
        else if (strncmp(tokens[1].value, "segmented", tokens[1].length) == 0) {
            lru_set_mode(LRU_MODE_SEGMENTED);
            conn_send(c, "OK: LRU mode set to segmented.\r\n", strlen("OK: LRU mode set to segmented.\r\n"));
        }
        else {
            conn_send(c, "ERROR: Invalid mode argument.\r\n", strlen("ERROR: Invalid mode argument.\r\n"));
        }
    }
    else if (strncmp(tokens[0].value, "temp_ttl", tokens[0].length) == 0) {
        if (ntokens != 2) {
            conn_send(c, "ERROR: 'temp_ttl' command requires a value.\r\n", strlen("ERROR: 'temp_ttl' command requires a value.\r\n"));
            return;
        }

        int temp_ttl = atoi(tokens[1].value);
        if (temp_ttl < 0) {
            conn_send(c, "ERROR: Invalid value for 'temp_ttl'.\r\n", strlen("ERROR: Invalid value for 'temp_ttl'.\r\n"));
            return;
        }

        lru_set_temp_ttl(temp_ttl);
        conn_send(c, "OK: Temporary TTL set.\r\n", strlen("OK: Temporary TTL set.\r\n"));
    }
    else {
        conn_send(c, "ERROR: Unknown command.\r\n", strlen("ERROR: Unknown command.\r\n"));
    }
}

void process_lru_command(conn *c, token_t *tokens, size_t ntokens) {
    if (ntokens < 2)
        return;

    if (strcmp(tokens[1].value, "tune") == 0) {
        if (ntokens != 5)
            return;

        uint32_t hot_percent, warm_percent, hot_age, warm_age;
        if (string_to_uint32(tokens[2].value, &hot_percent) != 0 ||
            string_to_uint32(tokens[3].value, &warm_percent) != 0 ||
            string_to_uint32(tokens[4].value, &hot_age) != 0 ||
            string_to_uint32(tokens[5].value, &warm_age) != 0) {
            conn_send(c, "ERROR: Invalid values for tuning.\r\n", strlen("ERROR: Invalid values for tuning.\r\n"));
            return;
        }

        if (hot_percent >= warm_percent) {
            conn_send(c, "ERROR: Hot percent must be less than warm percent.\r\n", strlen("ERROR: Hot percent must be less than warm percent.\r\n"));
            return;
        }

        c->hot_lru_percent = hot_percent;
        c->warm_lru_percent = warm_percent;
        c->hot_lru_age = hot_age;
        c->warm_lru_age = warm_age;
        conn_send(c, "Tuned LRU settings updated.\r\n", strlen("Tuned LRU settings updated.\r\n"));
    } else if (strcmp(tokens[1].value, "mode") == 0) {
        if (ntokens != 3)
            return;

        if (strcmp(tokens[2].value, "flat") == 0) {
            c->seg = false;
            conn_send(c, "Mode set to flat.\r\n", strlen("Mode set to flat.\r\n"));
        } else if (strcmp(tokens[2].value, "segmented") == 0) {
            c->seg = true;
            conn_send(c, "Mode set to segmented.\r\n", strlen("Mode set to segmented.\r\n"));
        } else {
            conn_send(c, "ERROR: Invalid mode argument.\r\n", strlen("ERROR: Invalid mode argument.\r\n"));
        }
    } else if (strcmp(tokens[1].value, "temp_ttl") == 0) {
        if (ntokens != 3)
            return;

        uint32_t temp_ttl;
        if (string_to_uint32(tokens[2].value, &temp_ttl) != 0) {
            conn_send(c, "ERROR: Invalid value for temp_ttl.\r\n", strlen("ERROR: Invalid value for temp_ttl.\r\n"));
            return;
        }

        c->temp_ttl = temp_ttl;
        conn_send(c, "Temporary TTL set.\r\n", strlen("Temporary TTL set.\r\n"));
    } else {
        conn_send(c, "ERROR: Unknown command.\r\n", strlen("ERROR: Unknown command.\r\n"));
    }
}

