            conn_send(c, "ERROR: Values out of valid range.\r\n", strlen("ERROR: Values out of valid range.\r\n"));
            return;
        }

        /* Update hot and warm settings */
        c->hot_percentage = hot_pct;
        c->warm_percentage = warm_pct;
        c->hot_age_factor = hot_age;
        c->warm_age_factor = warm_age;

        conn_send(c, "OK: LRU settings updated.\r\n", strlen("OK: LRU settings updated.\r\n"));
    }
    else if (strcmp(tokens[1].value, "mode") == 0) {
        if (ntokens != 3) {
            conn_send(c, "ERROR: Invalid number of arguments for 'mode' command.\r\n", strlen("ERROR: Invalid number of arguments for 'mode' command.\r\n"));
            return;
        }

        if (strcmp(tokens[2].value, "flat") == 0) {
            c->lru_mode = LRU_MODE_FLAT;
            conn_send(c, "OK: LRU mode set to flat.\r\n", strlen("OK: LRU mode set to flat.\r\n"));
        }
        else if (strcmp(tokens[2].value, "segmented") == 0) {
            c->lru_mode = LRU_MODE_SEGMENTED;
            conn_send(c, "OK: LRU mode set to segmented.\r\n", strlen("OK: LRU mode set to segmented.\r\n"));
        }
        else {
            conn_send(c, "ERROR: Invalid mode argument.\r\n", strlen("ERROR: Invalid mode argument.\r\n"));
        }
    }
    else if (strcmp(tokens[1].value, "temp_ttl") == 0) {
        if (ntokens != 3) {
            conn_send(c, "ERROR: Invalid number of arguments for 'temp_ttl' command.\r\n", strlen("ERROR: Invalid number of arguments for 'temp_ttl' command.\r\n"));
            return;
        }

        int temp_ttl;
        if (sscanf(tokens[2].value, "%d", &temp_ttl) != 1 || temp_ttl < 0) {
            conn_send(c, "ERROR: Invalid TTL value.\r\n", strlen("ERROR: Invalid TTL value.\r\n"));
            return;
